mkdeclimpl! {
impl MetaItem { # [doc = " For a single-segment meta item, returns its name; otherwise, returns `None`."] pub fn ident (& self) -> Option < Ident > { if let [PathSegment { ident , .. }] = self . path . segments [..] { Some (ident) } else { None } } pub fn name (& self) -> Option < Symbol > { self . ident () . map (| ident | ident . name) } pub fn has_name (& self , name : Symbol) -> bool { self . path == name } pub fn is_word (& self) -> bool { matches ! (self . kind , MetaItemKind :: Word) } pub fn meta_item_list (& self) -> Option < & [MetaItemInner] > { match & self . kind { MetaItemKind :: List (l) => Some (& * * l) , _ => None , } } # [doc = " ```text"] # [doc = " Example:"] # [doc = "     #[attribute(name = \"value\")]"] # [doc = "                 ^^^^^^^^^^^^^^"] # [doc = " ```"] pub fn name_value_literal (& self) -> Option < & MetaItemLit > { match & self . kind { MetaItemKind :: NameValue (v) => Some (v) , _ => None , } } # [doc = " This is used in case you want the value span instead of the whole attribute. Example:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[doc(alias = \"foo\")]"] # [doc = " ```"] # [doc = ""] # [doc = " In here, it'll return a span for `\"foo\"`."] pub fn name_value_literal_span (& self) -> Option < Span > { Some (self . name_value_literal () ? . span) } # [doc = " Returns the string value in:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[attribute = \"value\"]"] # [doc = "               ^^^^^^^"] # [doc = " ```"] # [doc = ""] # [doc = " It returns `None` in any other cases like:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[attr(\"value\")]"] # [doc = " ```"] pub fn value_str (& self) -> Option < Symbol > { match & self . kind { MetaItemKind :: NameValue (v) => v . kind . str () , _ => None , } } fn from_tokens (iter : & mut TokenStreamIter < '_ >) -> Option < MetaItem > { let tt = iter . next () . map (| tt | TokenTree :: uninterpolate (tt)) ; let path = match tt . as_deref () { Some (& TokenTree :: Token (Token { kind : ref kind @ (token :: Ident (..) | token :: PathSep) , span } , _ ,)) => 'arm : { let mut segments = if let & token :: Ident (name , _) = kind { if let Some (TokenTree :: Token (Token { kind : token :: PathSep , .. } , _)) = iter . peek () { iter . next () ; thin_vec ! [PathSegment :: from_ident (Ident :: new (name , span))] } else { break 'arm Path :: from_ident (Ident :: new (name , span)) ; } } else { thin_vec ! [PathSegment :: path_root (span)] } ; loop { if let Some (& TokenTree :: Token (Token { kind : token :: Ident (name , _) , span } , _)) = iter . next () . map (| tt | TokenTree :: uninterpolate (tt)) . as_deref () { segments . push (PathSegment :: from_ident (Ident :: new (name , span))) ; } else { return None ; } if let Some (TokenTree :: Token (Token { kind : token :: PathSep , .. } , _)) = iter . peek () { iter . next () ; } else { break ; } } let span = span . with_hi (segments . last () . unwrap () . ident . span . hi ()) ; Path { span , segments , tokens : None } } Some (TokenTree :: Delimited (_span , _spacing , Delimiter :: Invisible (InvisibleOrigin :: MetaVar (MetaVarKind :: Meta { .. } | MetaVarKind :: Path ,)) , _stream ,)) => { unreachable ! () } Some (TokenTree :: Token (Token { kind , .. } , _)) if kind . is_delim () => { panic ! ("Should be `AttrTokenTree::Delimited`, not delim tokens: {:?}" , tt) ; } _ => return None , } ; let list_closing_paren_pos = iter . peek () . map (| tt | tt . span () . hi ()) ; let kind = MetaItemKind :: from_tokens (iter) ? ; let hi = match & kind { MetaItemKind :: NameValue (lit) => lit . span . hi () , MetaItemKind :: List (..) => list_closing_paren_pos . unwrap_or (path . span . hi ()) , _ => path . span . hi () , } ; let span = path . span . with_hi (hi) ; Some (MetaItem { unsafety : Safety :: Default , path , kind , span }) } }
}